settings.custom_liquid:
{% assign community_url = 'https://example.com/community' %}

<style>
  .um-trust-bar {
    width: 100%;
    min-height: 46px;
    background-color: #f8f9fa;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 10px 15px;
    box-sizing: border-box;
    font-family: inherit;
  }

  .um-trust-inner {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    flex-wrap: wrap;
    color: #333333;
    font-size: 14px;
    line-height: 1.4;
    letter-spacing: 0.2px;
  }

  .um-rating {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    white-space: nowrap;
  }

  .um-stars {
    color: #f4c95d;
    font-size: 19px;
    letter-spacing: 2px;
    line-height: 1;
    white-space: nowrap;
  }

  .um-rating-score {
    font-weight: 700;
    color: #292929;
  }

  .um-review-count {
    font-weight: 400;
    color: #444444;
  }

  .um-trust-divider {
    width: 1px;
    height: 16px;
    background-color: #d4d4d4;
    flex-shrink: 0;
  }

  .um-community {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    white-space: nowrap;
  }

  .um-community-text {
    font-weight: 500;
    color: #333333;
  }

  .um-community-link {
    color: #222222;
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 2px;
    transition: opacity 0.2s ease;
  }

  .um-community-link:hover {
    opacity: 0.65;
  }

  @media screen and (max-width: 600px) {
    .um-trust-bar {
      padding: 10px 8px;
    }

    .um-trust-inner {
      gap: 6px;
      flex-direction: column;
      font-size: 12px;
      letter-spacing: 0;
    }

    .um-stars {
      font-size: 17px;
      letter-spacing: 1px;
    }

    .um-rating {
      gap: 6px;
    }

    .um-trust-divider {
      display: none;
    }

    .um-community {
      gap: 4px;
    }
  }
</style>

<div class="um-trust-bar">
  <div class="um-trust-inner">

    <div class="um-rating">
      <span class="um-stars" aria-label="5 stars">
        ★★★★★
      </span>

      <span class="um-rating-score">4.8</span>

      <span class="um-review-count">
        (1.5K+ Reviews)
      </span>
    </div>

    <span class="um-trust-divider"></span>

    <div class="um-community">
      <span class="um-community-text">
        18+ Tournaments Hosted.
      </span>

      <a
        href="{{ community_url }}"
        class="um-community-link"
        target="_blank"
        rel="noopener noreferrer"
      >
        Join the community!
      </a>
    </div>

  </div>
</div>
